(() => {
  'use strict';

  const DATA = window.GCSE_COURSE_DATA || { topics:[] };
  const state = {
    tab:'live', classes:[], members:[], resources:[], plans:[], departments:[], schools:[], schoolMemberships:[],
    liveSession:null, liveSnapshot:null, generatedResource:null, generatedPlan:null, presentation:null,
    intervention:null, report:null, parentSummary:null, departmentDashboard:null, collaboration:[], comments:[], schoolDashboard:null,
    loading:false
  };

  const TABS = [
    ['live','8','Live Classroom'],['resources','9','Resource Generator'],['planning','10','Lesson Planning'],['presentation','11','Presentation Controls'],
    ['interventions','12','Intervention Dashboard'],['reports','13','Reports'],['parents','14','Parent Summaries'],['department','15','Department Dashboard'],
    ['collaboration','16','Teacher Collaboration'],['school','17','School Admin']
  ];
  const esc = (v='') => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const sb = () => window.GCSE_AUTH?.client || null;
  const session = () => window.GCSE_AUTH?.getSession?.() || null;
  const profile = () => window.GCSE_AUTH?.getProfile?.() || null;
  const uid = () => session()?.user?.id || '';
  const teacherEligible = () => Boolean(profile()?.is_admin || window.GCSE_ACCESS?.can?.('teacher_tools'));
  const schoolAdminEligible = () => Boolean(profile()?.is_admin || ['school_admin','platform_admin'].includes(profile()?.role));
  const topic = id => DATA.topics?.find(t=>t.id===id) || null;
  const klass = id => state.classes.find(c=>c.id===id) || null;
  const titleCase = v => String(v||'').replace(/_/g,' ').replace(/\b\w/g,c=>c.toUpperCase());
  const fmt = v => v ? new Date(v).toLocaleString('en-GB',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}) : '—';
  const topicOptions = (selected='') => DATA.topics.map(t=>`<option value="${esc(t.id)}" ${t.id===selected?'selected':''}>${esc(t.code)} · ${esc(t.title)}</option>`).join('');
  const classOptions = (selected='', allLabel='Choose class…') => `<option value="">${esc(allLabel)}</option>${state.classes.filter(c=>!c.archived).map(c=>`<option value="${c.id}" ${c.id===selected?'selected':''}>${esc(c.name)} · ${esc(c.year_group)}</option>`).join('')}`;
  const memberName = id => state.members.find(m=>m.student_id===id)?.display_name || state.members.find(m=>m.student_id===id)?.student_email || 'Student';
  const joinedFor = classId => state.members.filter(m=>m.class_id===classId && m.status==='joined' && m.student_id);

  function message(text='',kind='info'){
    const box=document.querySelector('#gcseTeacherSuiteModal [data-suite-message]');
    if(!box)return; box.hidden=!text; box.className=`teacher-suite-message ${kind}`; box.textContent=text;
  }

  function ensureButton(){
    const header=document.querySelector('#gcseTeacherPlatformModal .teacher-platform-header');
    if(!header || !teacherEligible()) return;
    if(document.getElementById('gcseTeacherSuiteButton')) return;
    const btn=document.createElement('button');btn.id='gcseTeacherSuiteButton';btn.type='button';btn.className='teacher-suite-open';btn.textContent='Teacher Suite';
    btn.addEventListener('click',()=>openSuite());
    const close=header.querySelector('.teacher-close');(close||header).insertAdjacentElement(close?'beforebegin':'beforeend',btn);
  }

  function ensureModal(){
    let modal=document.getElementById('gcseTeacherSuiteModal'); if(modal)return modal;
    modal=document.createElement('div');modal.id='gcseTeacherSuiteModal';modal.className='teacher-suite-modal';modal.hidden=true;
    modal.innerHTML=`<div class="teacher-suite-backdrop" data-suite-close></div><section class="teacher-suite-shell" role="dialog" aria-modal="true" aria-labelledby="gcseSuiteTitle">
      <header class="teacher-suite-header"><div><span class="teacher-suite-kicker">GCSE Science · Teacher Platform</span><h2 id="gcseSuiteTitle">Teacher Suite</h2><p>Live teaching, planning, reporting and school tools.</p></div><button type="button" data-suite-close aria-label="Close">×</button></header>
      <div class="teacher-suite-layout"><nav class="teacher-suite-nav" data-suite-nav></nav><main class="teacher-suite-main"><div data-suite-message class="teacher-suite-message" hidden></div><div data-suite-body></div></main></div></section>`;
    document.body.appendChild(modal);
    modal.querySelectorAll('[data-suite-close]').forEach(x=>x.addEventListener('click',closeSuite));
    document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!modal.hidden)closeSuite();});
    return modal;
  }

  function renderNav(){
    const nav=document.querySelector('#gcseTeacherSuiteModal [data-suite-nav]');if(!nav)return;
    nav.innerHTML=TABS.map(([id,n,label])=>`<button type="button" data-suite-tab="${id}" class="${state.tab===id?'active':''} ${id==='school'&&!schoolAdminEligible()?'restricted':''}"><span>${n}</span><b>${esc(label)}</b></button>`).join('');
    nav.querySelectorAll('[data-suite-tab]').forEach(btn=>btn.addEventListener('click',()=>{state.tab=btn.dataset.suiteTab;renderNav();renderTab();}));
  }

  async function loadBase(){
    const client=sb(), userId=uid(); if(!client||!userId)return;
    state.loading=true;
    const [classes,members,resources,plans,departments,schoolMemberships,schools]=await Promise.all([
      client.from('gcse_classes').select('*').eq('teacher_id',userId).order('archived').order('created_at',{ascending:false}),
      client.from('gcse_class_members').select('*').eq('teacher_id',userId).order('display_name'),
      client.from('gcse_teacher_resources').select('*').eq('teacher_id',userId).order('created_at',{ascending:false}).limit(100),
      client.from('gcse_lesson_plans').select('*').eq('teacher_id',userId).order('created_at',{ascending:false}).limit(100),
      client.from('gcse_departments').select('*').order('created_at',{ascending:false}),
      client.from('gcse_school_members').select('*').eq('user_id',userId),
      client.from('gcse_schools').select('*').order('created_at',{ascending:false})
    ]);
    state.loading=false;
    state.classes=classes.data||[];state.members=members.data||[];state.resources=resources.data||[];state.plans=plans.data||[];state.departments=departments.data||[];state.schoolMemberships=schoolMemberships.data||[];state.schools=schools.data||[];
  }

  async function openSuite(tab){
    if(!teacherEligible()){window.GCSE_ACCESS?.showUpgrade?.('teacher_tools','Teacher Suite');return;}
    if(tab)state.tab=tab;
    const modal=ensureModal();modal.hidden=false;document.body.classList.add('teacher-suite-open');
    const body=modal.querySelector('[data-suite-body]');body.innerHTML='<div class="teacher-suite-loading">Loading teacher tools…</div>';
    try{await loadBase();renderNav();renderTab();}catch(error){console.error('[Teacher Suite]',error);body.innerHTML='<div class="teacher-suite-empty"><strong>Teacher Suite could not load.</strong><p>Check your Teacher access and try again.</p></div>';}
  }
  function closeSuite(){const m=document.getElementById('gcseTeacherSuiteModal');if(m)m.hidden=true;document.body.classList.remove('teacher-suite-open');}
  function body(){return document.querySelector('#gcseTeacherSuiteModal [data-suite-body]');}
  function renderTab(){message('');const fn={live:renderLive,resources:renderResources,planning:renderPlanning,presentation:renderPresentation,interventions:renderInterventions,reports:renderReports,parents:renderParents,department:renderDepartment,collaboration:renderCollaboration,school:renderSchool}[state.tab];fn?.();}

  // Phase 8 — Live Classroom
  async function loadLive(){
    const client=sb();if(!client)return;
    const {data}=await client.from('gcse_live_classroom_sessions').select('*').eq('teacher_id',uid()).eq('status','live').order('started_at',{ascending:false}).limit(1).maybeSingle();
    state.liveSession=data||null;
    if(state.liveSession){const snap=await client.rpc('gcse_live_classroom_snapshot',{p_session_id:state.liveSession.id});state.liveSnapshot=snap.error?null:snap.data;}
  }
  async function renderLive(){
    const root=body();if(!root)return;root.innerHTML='<div class="teacher-suite-loading">Loading live classroom…</div>';await loadLive();
    if(!state.liveSession){
      root.innerHTML=`${phaseHead(8,'Live Classroom','Launch a live check-in, question or exit ticket for a class. Student responses appear in one place.')}
        <form class="suite-form suite-card" data-live-start><label>Class<select name="class_id" required>${classOptions()}</select></label><label>Topic<select name="topic_id"><option value="">General science</option>${topicOptions()}</select></label><label class="wide">Session title<input name="title" maxlength="160" value="GCSE Science live classroom"></label><div class="wide"><button class="button primary" type="submit">Start live classroom</button></div></form>`;
      root.querySelector('[data-live-start]')?.addEventListener('submit',startLive);return;
    }
    const s=state.liveSession,snap=state.liveSnapshot||{},responses=snap.responses||[];
    root.innerHTML=`${phaseHead(8,'Live Classroom','Run quick whole-class checks while students respond from their signed-in accounts.')}
      <div class="suite-kpis"><article><span>Join code</span><strong>${esc(s.join_code)}</strong><small>Share with this class</small></article><article><span>Responses</span><strong>${responses.length}</strong><small>saved in this session</small></article><article><span>Activity</span><strong>${esc(titleCase(s.current_activity))}</strong><small>started ${esc(fmt(s.started_at))}</small></article></div>
      <section class="suite-card"><div class="suite-card-head"><div><h3>${esc(s.title)}</h3><p>${esc(klass(s.class_id)?.name||'Class')} · ${esc(topic(s.topic_id)?.title||'General')}</p></div><button class="button danger" data-live-end>End session</button></div>
        <div class="live-activity-grid"><button data-live-activity="welcome">Welcome</button><button data-live-activity="check_in">Check-in</button><button data-live-activity="question">Question</button><button data-live-activity="exit_ticket">Exit ticket</button></div>
        <label class="suite-prompt">Prompt<textarea rows="2" data-live-prompt placeholder="e.g. Explain why diffusion is faster at a higher temperature.">${esc(s.activity_payload?.prompt||'')}</textarea></label>
        <div class="suite-inline"><button class="button primary" data-live-send>Send activity to students</button><button class="button" data-live-refresh>Refresh responses</button></div>
      </section>
      <section class="suite-card"><div class="suite-card-head"><div><h3>Student responses</h3><p>Use responses formatively; they are not automatically treated as grades.</p></div></div><div class="live-response-list">${responses.length?responses.map(r=>`<article><div><strong>${esc(r.name||memberName(r.studentId))}</strong><span>${esc(titleCase(r.promptId))} · ${esc(fmt(r.updatedAt))}</span></div><p>${esc(r.response||'No text response')}</p></article>`).join(''):'<div class="teacher-suite-empty">No responses yet.</div>'}</div></section>`;
    let selected=s.current_activity||'welcome';root.querySelectorAll('[data-live-activity]').forEach(b=>{if(b.dataset.liveActivity===selected)b.classList.add('active');b.addEventListener('click',()=>{selected=b.dataset.liveActivity;root.querySelectorAll('[data-live-activity]').forEach(x=>x.classList.toggle('active',x===b));});});
    root.querySelector('[data-live-send]')?.addEventListener('click',()=>sendLiveActivity(selected));
    root.querySelector('[data-live-refresh]')?.addEventListener('click',renderLive);
    root.querySelector('[data-live-end]')?.addEventListener('click',endLive);
  }
  async function startLive(e){e.preventDefault();const fd=new FormData(e.currentTarget);const {data,error}=await sb().rpc('gcse_start_live_classroom',{p_class_id:String(fd.get('class_id')||''),p_topic_id:String(fd.get('topic_id')||''),p_title:String(fd.get('title')||'Live classroom')});if(error){message(error.message,'error');return;}state.liveSession={id:data.id,class_id:data.classId,topic_id:data.topicId,title:data.title,join_code:data.joinCode,status:data.status,current_activity:'welcome',activity_payload:{}};message('Live classroom started.','success');renderLive();}
  async function sendLiveActivity(activity){const prompt=body().querySelector('[data-live-prompt]')?.value?.trim()||'';if(['check_in','question','exit_ticket'].includes(activity)&&!prompt){message('Add a prompt before sending this activity.','error');return;}const payload={prompt,type:'short',sentAt:new Date().toISOString()};const {error}=await sb().rpc('gcse_update_live_classroom',{p_session_id:state.liveSession.id,p_activity:activity,p_payload:payload});if(error){message(error.message,'error');return;}message('Activity sent to students.','success');renderLive();}
  async function endLive(){if(!confirm('End this live classroom session?'))return;const {error}=await sb().rpc('gcse_end_live_classroom',{p_session_id:state.liveSession.id});if(error){message(error.message,'error');return;}state.liveSession=null;state.liveSnapshot=null;message('Live classroom ended.','success');renderLive();}

  // Phase 9 — Teacher Resource Generator
  function resourceContent(type,t){
    const quiz=(t?.quiz||[]).map(q=>String(q?.[0]||'')).filter(Boolean);const practicals=t?.practicals||[];const lessons=(t?.lessons||[]).map(l=>Array.isArray(l)?l[0]:l?.title).filter(Boolean);
    const base={topicId:t?.id,topicCode:t?.code,topicTitle:t?.title,summary:t?.summary,generatedAt:new Date().toISOString(),sections:[]};
    if(type==='retrieval')base.sections=[{title:'Do now · retrieval',items:(quiz.length?quiz:lessons.slice(0,5).map(x=>`What do you remember about ${x}?`)).slice(0,5)},{title:'Self-check',items:['Correct using your notes only after attempting every question.','Star the question you most need to revisit.']}];
    if(type==='worksheet')base.sections=[{title:'Key knowledge',items:lessons.slice(0,8).map(x=>`Explain the science behind: ${x}.`)},{title:'Apply',items:(quiz.length?quiz:lessons).slice(0,5)},{title:'Exam focus',items:[`Write a six-mark response connecting the main ideas in ${t?.title}.`]}];
    if(type==='exit_ticket')base.sections=[{title:'Exit ticket',items:[...(quiz.slice(0,2)),`What is the most important idea from ${t?.title}?`,`What still needs clarification?`]}];
    if(type==='homework')base.sections=[{title:'Retrieval',items:(quiz.length?quiz:lessons.slice(0,4).map(x=>`Define or explain ${x}.`)).slice(0,4)},{title:'Independent application',items:[`Create a labelled explanation or worked example for one key process in ${t?.title}.`,`Write one exam-style question for this topic and then answer it fully.`]}];
    if(type==='practical')base.sections=[{title:'Required practical focus',items:practicals.length?practicals:['No required practical is listed for this topic. Use this sheet for relevant investigative skills.']},{title:'Planning checklist',items:['Identify the independent, dependent and control variables.','Describe a repeatable method and appropriate measuring equipment.','State the main safety controls.','Choose a suitable table and graph.']},{title:'Evaluation',items:['Identify one source of uncertainty.','Suggest a realistic improvement and explain how it improves the evidence.']}];
    if(type==='revision')base.sections=[{title:'Revision checklist',items:lessons.map(x=>`□ ${x}`)},{title:'Retrieval questions',items:quiz.slice(0,5)},{title:'Exam readiness',items:['Can I use precise scientific vocabulary?','Can I apply the idea in an unfamiliar context?','Can I complete relevant calculations with units?']}];
    if(type==='custom')base.sections=[{title:'Teacher resource',items:[`Use ${t?.title} course content to create your own activity.`]}];
    return base;
  }
  function renderResourcePreview(content){return `<div class="resource-preview"><header><span>${esc(content.topicCode||'GCSE')}</span><h3>${esc(content.topicTitle||'Science resource')}</h3><p>${esc(content.summary||'')}</p></header>${(content.sections||[]).map(s=>`<section><h4>${esc(s.title)}</h4><ol>${(s.items||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ol></section>`).join('')}</div>`;}
  function renderResources(){const root=body();if(!root)return;root.innerHTML=`${phaseHead(9,'Teacher Resource Generator','Build printable AQA-aligned starters, worksheets, homework, practical sheets and revision resources from the course map.')}
    <div class="suite-two-col"><form class="suite-card suite-form" data-resource-generator><label>Resource type<select name="type"><option value="retrieval">Retrieval starter</option><option value="worksheet">Worksheet</option><option value="exit_ticket">Exit ticket</option><option value="homework">Homework</option><option value="practical">Practical sheet</option><option value="revision">Revision pack</option></select></label><label>Topic<select name="topic_id">${topicOptions()}</select></label><label class="wide">Title<input name="title" maxlength="160" placeholder="Auto title"></label><div class="wide suite-inline"><button class="button primary" type="submit">Generate resource</button>${state.generatedResource?'<button class="button" type="button" data-resource-save>Save resource</button><button class="button" type="button" data-resource-print>Print</button>':''}</div></form><section class="suite-card" data-resource-preview>${state.generatedResource?renderResourcePreview(state.generatedResource.content):'<div class="teacher-suite-empty">Generate a resource to preview it here.</div>'}</section></div>
    <section class="suite-card"><div class="suite-card-head"><div><h3>Saved resources</h3><p>${state.resources.length} saved</p></div></div><div class="suite-list">${state.resources.length?state.resources.map(r=>`<article><div><span>${esc(titleCase(r.resource_type))}</span><strong>${esc(r.title)}</strong><small>${esc(topic(r.topic_id)?.code||'General')} · ${esc(fmt(r.created_at))}</small></div><div><button class="button" data-resource-open="${r.id}">Preview</button><button class="button danger ghost" data-resource-delete="${r.id}">Delete</button></div></article>`).join(''):'<div class="teacher-suite-empty">No saved resources yet.</div>'}</div></section>`;
    root.querySelector('[data-resource-generator]')?.addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(e.currentTarget),t=topic(String(fd.get('topic_id')||'')),type=String(fd.get('type')||'retrieval');if(!t)return;state.generatedResource={title:String(fd.get('title')||'').trim()||`${t.code} ${t.title} · ${titleCase(type)}`,type,topicId:t.id,content:resourceContent(type,t)};renderResources();});
    root.querySelector('[data-resource-save]')?.addEventListener('click',saveGeneratedResource);root.querySelector('[data-resource-print]')?.addEventListener('click',()=>printResource(state.generatedResource));
    root.querySelectorAll('[data-resource-open]').forEach(b=>b.addEventListener('click',()=>{const r=state.resources.find(x=>x.id===b.dataset.resourceOpen);if(r){state.generatedResource={title:r.title,type:r.resource_type,topicId:r.topic_id,content:r.content};renderResources();}}));
    root.querySelectorAll('[data-resource-delete]').forEach(b=>b.addEventListener('click',()=>deleteResource(b.dataset.resourceDelete)));
  }
  async function saveGeneratedResource(){const r=state.generatedResource;if(!r)return;const {error}=await sb().from('gcse_teacher_resources').insert({teacher_id:uid(),topic_id:r.topicId,resource_type:r.type,title:r.title,content:r.content});if(error){message(error.message,'error');return;}await loadBase();message('Resource saved.','success');renderResources();}
  async function deleteResource(id){if(!confirm('Delete this saved resource?'))return;const {error}=await sb().from('gcse_teacher_resources').delete().eq('id',id).eq('teacher_id',uid());if(error){message(error.message,'error');return;}await loadBase();renderResources();}
  function printResource(r){if(!r)return;const w=window.open('','_blank');if(!w){message('Allow pop-ups to print this resource.','error');return;}w.document.write(`<!doctype html><html><head><title>${esc(r.title)}</title><style>body{font-family:Arial,sans-serif;max-width:850px;margin:40px auto;color:#111}h1{font-size:26px}section{margin:28px 0}li{margin:14px 0;line-height:1.45}@media print{button{display:none}}</style></head><body><h1>${esc(r.title)}</h1>${renderResourcePreview(r.content)}<script>window.onload=()=>window.print()<\/script></body></html>`);w.document.close();}

  // Phase 10 — Lesson Planning
  function lessonList(t){return (t?.lessons||[]).map(l=>Array.isArray(l)?l[0]:l?.title).filter(Boolean);}
  function makePlan(t,lessonTitle,duration=55){
    const d=Math.max(20,Math.min(120,Number(duration)||55));const ratio=[.12,.22,.17,.18,.22,.09];let used=0;const times=ratio.map((r,i)=>i===ratio.length-1?d-used:Math.max(2,Math.round(d*r)));times.slice(0,-1).forEach(x=>used+=x);
    const quiz=(t?.quiz||[]).map(q=>q?.[0]).filter(Boolean);
    return {objectives:[`Describe the key science in ${lessonTitle}.`,`Apply ${t?.title} knowledge to questions and unfamiliar contexts.`,`Use precise AQA scientific vocabulary and, where relevant, correct units.`],sequence:[
      {stage:'Retrieval starter',minutes:times[0],detail:(quiz.slice(0,3).join(' · ')||`Recall prior knowledge needed for ${lessonTitle}.`)},
      {stage:'Knowledge build',minutes:times[1],detail:`Teacher explanation and visual modelling of ${lessonTitle}.`},
      {stage:'Worked model',minutes:times[2],detail:'Model one exam-style response or calculation, thinking aloud about command words and evidence.'},
      {stage:'Guided practice',minutes:times[3],detail:'Students complete scaffolded questions; pause for whole-class checks and address misconceptions.'},
      {stage:'Independent application',minutes:times[4],detail:`Independent GCSE questions linking ${lessonTitle} to the wider ${t?.title} topic.`},
      {stage:'Exit check',minutes:times[5],detail:'Three-question exit ticket: knowledge, application and confidence/next step.'}
    ]};
  }
  function renderPlanning(){const root=body();if(!root)return;root.innerHTML=`${phaseHead(10,'Teacher Lesson Planning','Turn any course lesson into an editable teaching sequence with timings, objectives, checks and resources.')}
    <div class="suite-two-col"><form class="suite-card suite-form" data-plan-generator><label>Class<select name="class_id">${classOptions('', 'Optional class')}</select></label><label>Topic<select name="topic_id" data-plan-topic>${topicOptions()}</select></label><label class="wide">Lesson<select name="lesson_title" data-plan-lesson></select></label><label>Duration (minutes)<input name="duration" type="number" min="20" max="120" value="55"></label><label>Planned date<input name="planned_for" type="date"></label><div class="wide"><button class="button primary" type="submit">Build lesson plan</button></div></form><section class="suite-card">${state.generatedPlan?planPreview(state.generatedPlan):'<div class="teacher-suite-empty">Choose a lesson to generate a teaching plan.</div>'}</section></div>
    <section class="suite-card"><div class="suite-card-head"><div><h3>Saved lesson plans</h3><p>${state.plans.length} saved</p></div></div><div class="suite-list">${state.plans.length?state.plans.map(p=>`<article><div><span>${esc(titleCase(p.status))}</span><strong>${esc(p.lesson_title)}</strong><small>${esc(topic(p.topic_id)?.code||'GCSE')} · ${p.duration_minutes} min${p.planned_for?` · ${esc(p.planned_for)}`:''}</small></div><div><button class="button" data-plan-open="${p.id}">Open</button><button class="button" data-plan-present="${p.id}">Present</button></div></article>`).join(''):'<div class="teacher-suite-empty">No lesson plans saved yet.</div>'}</div></section>`;
    const form=root.querySelector('[data-plan-generator]'),topicSelect=form?.elements.topic_id,lessonSelect=form?.elements.lesson_title;
    const refreshLessons=()=>{const t=topic(topicSelect.value);lessonSelect.innerHTML=lessonList(t).map(x=>`<option>${esc(x)}</option>`).join('');};topicSelect?.addEventListener('change',refreshLessons);refreshLessons();
    form?.addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(e.currentTarget),t=topic(String(fd.get('topic_id'))),lesson=String(fd.get('lesson_title')||'');if(!t||!lesson)return;const built=makePlan(t,lesson,fd.get('duration'));state.generatedPlan={classId:String(fd.get('class_id')||''),topicId:t.id,lessonTitle:lesson,duration:Number(fd.get('duration'))||55,plannedFor:String(fd.get('planned_for')||''),...built};renderPlanning();});
    root.querySelector('[data-plan-save]')?.addEventListener('click',savePlan);root.querySelectorAll('[data-plan-open]').forEach(b=>b.addEventListener('click',()=>{const p=state.plans.find(x=>x.id===b.dataset.planOpen);if(p){state.generatedPlan={id:p.id,classId:p.class_id||'',topicId:p.topic_id,lessonTitle:p.lesson_title,duration:p.duration_minutes,plannedFor:p.planned_for||'',objectives:p.objectives||[],sequence:p.lesson_sequence||[],notes:p.teacher_notes||''};renderPlanning();}}));root.querySelectorAll('[data-plan-present]').forEach(b=>b.addEventListener('click',()=>{const p=state.plans.find(x=>x.id===b.dataset.planPresent);if(p){state.presentation={plan:p};state.tab='presentation';renderNav();renderPresentation();}}));
  }
  function planPreview(p){return `<div class="plan-preview"><div class="suite-card-head"><div><span>${esc(topic(p.topicId)?.code||'GCSE')}</span><h3>${esc(p.lessonTitle)}</h3><p>${p.duration} minutes</p></div><button class="button primary" data-plan-save>${p.id?'Save changes':'Save plan'}</button></div><h4>Learning objectives</h4><ul>${(p.objectives||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h4>Lesson sequence</h4><div class="plan-timeline">${(p.sequence||[]).map(s=>`<article><b>${s.minutes} min</b><div><strong>${esc(s.stage)}</strong><p>${esc(s.detail)}</p></div></article>`).join('')}</div></div>`;}
  async function savePlan(){const p=state.generatedPlan;if(!p)return;const payload={teacher_id:uid(),class_id:p.classId||null,topic_id:p.topicId,lesson_title:p.lessonTitle,duration_minutes:p.duration,planned_for:p.plannedFor||null,objectives:p.objectives,lesson_sequence:p.sequence,teacher_notes:p.notes||'',status:'ready'};let result;if(p.id)result=await sb().from('gcse_lesson_plans').update(payload).eq('id',p.id).eq('teacher_id',uid());else result=await sb().from('gcse_lesson_plans').insert(payload);if(result.error){message(result.error.message,'error');return;}await loadBase();message('Lesson plan saved.','success');renderPlanning();}

  // Phase 11 — Classroom Presentation Controls
  async function renderPresentation(){const root=body();if(!root)return;let live=null;const q=await sb().from('gcse_presentation_sessions').select('*').eq('teacher_id',uid()).eq('status','live').order('started_at',{ascending:false}).limit(1).maybeSingle();live=q.data||null;if(live)state.presentation={session:live,plan:state.plans.find(p=>p.lesson_title===live.lesson_title)||state.presentation?.plan};
    if(!state.presentation?.session){root.innerHTML=`${phaseHead(11,'Classroom Presentation Controls','Start a lesson presentation with slide position, blackout, question/answer state and a synced classroom timer.')}
      <form class="suite-card suite-form" data-present-start><label>Class<select name="class_id">${classOptions('', 'Optional class')}</select></label><label>Lesson plan<select name="plan_id"><option value="">Choose saved plan…</option>${state.plans.map(p=>`<option value="${p.id}" ${state.presentation?.plan?.id===p.id?'selected':''}>${esc(p.lesson_title)}</option>`).join('')}</select></label><label>Or topic<select name="topic_id"><option value="">Choose topic…</option>${topicOptions()}</select></label><div class="wide"><button class="button primary" type="submit">Start presentation controls</button></div></form>`;root.querySelector('[data-present-start]')?.addEventListener('submit',startPresentation);return;}
    const s=state.presentation.session,p=state.presentation.plan;
    root.innerHTML=`${phaseHead(11,'Classroom Presentation Controls','Keep the presentation state simple enough to use while teaching.')}
      <section class="suite-card presentation-control"><div class="suite-card-head"><div><span>Live presentation</span><h3>${esc(s.lesson_title||p?.lesson_title||topic(s.topic_id)?.title||'GCSE Science')}</h3><p>${esc(klass(s.class_id)?.name||'No class selected')}</p></div><button class="button danger" data-present-end>End</button></div>
      <div class="presentation-state ${esc(s.display_mode)}"><strong>Slide ${Number(s.slide_index)+1}</strong><span>${esc(titleCase(s.display_mode))}</span><b data-present-timer>${timerText(s.timer_ends_at)}</b></div>
      <div class="presentation-controls"><button data-slide-step="-1">← Previous</button><button data-slide-step="1">Next →</button><button data-display-mode="normal">Normal</button><button data-display-mode="blackout">Blackout</button><button data-display-mode="question">Question</button><button data-display-mode="answer">Reveal answer</button></div>
      <div class="suite-inline presentation-timer"><input type="number" min="1" max="60" value="5" data-timer-minutes aria-label="Timer minutes"><button class="button" data-start-timer>Start timer</button><button class="button" data-clear-timer>Clear timer</button><button class="button primary" data-open-course>Open course presentation</button></div></section>`;
    root.querySelectorAll('[data-slide-step]').forEach(b=>b.addEventListener('click',()=>updatePresentation({slide_index:Math.max(0,Number(s.slide_index)+Number(b.dataset.slideStep))})));root.querySelectorAll('[data-display-mode]').forEach(b=>b.addEventListener('click',()=>updatePresentation({display_mode:b.dataset.displayMode})));root.querySelector('[data-start-timer]')?.addEventListener('click',()=>{const mins=Math.max(1,Math.min(60,Number(root.querySelector('[data-timer-minutes]').value)||5));updatePresentation({timer_ends_at:new Date(Date.now()+mins*60000).toISOString()});});root.querySelector('[data-clear-timer]')?.addEventListener('click',()=>updatePresentation({timer_ends_at:null}));root.querySelector('[data-present-end]')?.addEventListener('click',endPresentation);root.querySelector('[data-open-course]')?.addEventListener('click',()=>openCoursePresentation(s));
  }
  function timerText(v){if(!v)return 'No timer';const ms=new Date(v).getTime()-Date.now();if(ms<=0)return 'Timer finished';const m=Math.floor(ms/60000),s=Math.floor((ms%60000)/1000);return `${m}:${String(s).padStart(2,'0')}`;}
  async function startPresentation(e){e.preventDefault();const fd=new FormData(e.currentTarget),p=state.plans.find(x=>x.id===String(fd.get('plan_id')||'')),topicId=p?.topic_id||String(fd.get('topic_id')||'')||null,title=p?.lesson_title||topic(topicId)?.title||'GCSE Science';const {data,error}=await sb().from('gcse_presentation_sessions').insert({teacher_id:uid(),class_id:String(fd.get('class_id')||'')||p?.class_id||null,topic_id:topicId,lesson_title:title,status:'live'}).select('*').single();if(error){message(error.message,'error');return;}state.presentation={session:data,plan:p||null};renderPresentation();}
  async function updatePresentation(patch){const s=state.presentation?.session;if(!s)return;const {data,error}=await sb().from('gcse_presentation_sessions').update({...patch,updated_at:new Date().toISOString()}).eq('id',s.id).eq('teacher_id',uid()).select('*').single();if(error){message(error.message,'error');return;}state.presentation.session=data;renderPresentation();}
  async function endPresentation(){const s=state.presentation?.session;if(!s)return;await sb().from('gcse_presentation_sessions').update({status:'ended',ended_at:new Date().toISOString(),updated_at:new Date().toISOString()}).eq('id',s.id).eq('teacher_id',uid());state.presentation=null;renderPresentation();}
  function openCoursePresentation(s){closeSuite();if(s.topic_id&&typeof window.openTopic==='function'){window.openTopic(s.topic_id);setTimeout(()=>{document.querySelector('#contentTabs [data-tab="presentation"],#contentTabs [data-tab="presentations"],#contentTabs [data-tab="lessons"]')?.click();},100);}}

  // Phase 12 — Intervention Dashboard
  async function loadInterventionDashboard(classId=''){const {data,error}=await sb().rpc('gcse_intervention_dashboard',{p_class_id:classId||null});if(error){message(error.message,'error');return null;}state.intervention=data;return data;}
  async function renderInterventions(){const root=body();if(!root)return;root.innerHTML='<div class="teacher-suite-loading">Loading intervention evidence…</div>';if(!state.intervention)await loadInterventionDashboard();const d=state.intervention||{summary:{},rows:[]},s=d.summary||{},rows=d.rows||[];root.innerHTML=`${phaseHead(12,'Intervention Dashboard','See who has been targeted, whether follow-up was completed and whether mastery improved.')}
    <div class="suite-filter"><label>Class<select data-intervention-class>${classOptions('', 'All my classes')}</select></label><button class="button" data-intervention-refresh>Refresh</button></div><div class="suite-kpis"><article><span>Active</span><strong>${s.active||0}</strong><small>published interventions</small></article><article><span>Students</span><strong>${s.students||0}</strong><small>targeted learners</small></article><article><span>Target met</span><strong>${s.targetMet||0}</strong><small>mastery checks</small></article><article><span>Avg improvement</span><strong>${s.averageImprovement==null?'—':`${s.averageImprovement > 0?'+':''}${s.averageImprovement}`}</strong><small>percentage points</small></article></div>
    <section class="suite-card"><div class="suite-table"><div class="suite-table-row head"><span>Student</span><span>Topic</span><span>Baseline</span><span>Re-test</span><span>Change</span><span>Status</span></div>${rows.length?rows.map(r=>`<div class="suite-table-row"><span><b>${esc(r.studentName||memberName(r.studentId))}</b><small>${esc(r.className||'')}</small></span><span>${esc(r.topicCode||'')} ${esc(r.topicTitle||'')}</span><span>${r.baseline==null?'—':r.baseline+'%'}</span><span>${r.retest==null?'—':r.retest+'%'}</span><span class="${Number(r.improvement)>0?'positive':''}">${r.improvement==null?'—':`${Number(r.improvement)>0?'+':''}${r.improvement}`}</span><span>${r.targetMet?'Target met':esc(titleCase(r.attemptStatus||r.status))}</span></div>`).join(''):'<div class="teacher-suite-empty">No intervention evidence yet.</div>'}</div></section>`;
    root.querySelector('[data-intervention-refresh]')?.addEventListener('click',async()=>{state.intervention=null;await loadInterventionDashboard(root.querySelector('[data-intervention-class]').value);renderInterventions();});}

  // Phase 13 — Reports
  async function renderReports(){const root=body();if(!root)return;root.innerHTML=`${phaseHead(13,'Teacher Reports','Build a class snapshot from homework, assessment and intervention evidence, then export it for meetings or planning.')}
    <form class="suite-card suite-form" data-report-form><label>Class<select name="class_id" required>${classOptions()}</select></label><label>Report type<select name="report_type"><option value="class_progress">Class progress</option><option value="assessment">Assessment</option><option value="homework">Homework</option><option value="intervention">Intervention</option></select></label><div class="wide"><button class="button primary" type="submit">Generate report</button></div></form>${state.report?reportHtml(state.report.payload||state.report):''}`;root.querySelector('[data-report-form]')?.addEventListener('submit',generateReport);root.querySelector('[data-report-csv]')?.addEventListener('click',()=>exportReportCsv(state.report?.payload||state.report));root.querySelector('[data-report-print]')?.addEventListener('click',()=>window.print());}
  async function generateReport(e){e.preventDefault();const fd=new FormData(e.currentTarget);const {data,error}=await sb().rpc('gcse_build_teacher_report',{p_class_id:String(fd.get('class_id')||''),p_report_type:String(fd.get('report_type')||'class_progress')});if(error){message(error.message,'error');return;}state.report=data;message('Report generated and saved.','success');renderReports();}
  function reportHtml(p){const s=p.summary||{},students=p.students||[];return `<section class="suite-card report-output"><div class="suite-card-head"><div><span>Generated ${esc(fmt(p.generatedAt))}</span><h3>${esc(p.className||'Class report')}</h3><p>${esc(p.yearGroup||'')} · ${esc(titleCase(p.subject||'science'))}</p></div><div class="suite-inline"><button class="button" data-report-csv>Export CSV</button><button class="button" data-report-print>Print</button></div></div><div class="suite-kpis compact"><article><span>Students</span><strong>${s.students||0}</strong></article><article><span>Assignments</span><strong>${s.assignments||0}</strong></article><article><span>Assessment avg</span><strong>${s.assessmentAverage==null?'—':s.assessmentAverage+'%'}</strong></article><article><span>Interventions</span><strong>${s.interventions||0}</strong></article></div><div class="suite-table"><div class="suite-table-row report head"><span>Student</span><span>Assessment</span><span>Homework</span><span>Interventions</span><span>Targets met</span></div>${students.map(x=>`<div class="suite-table-row report"><span>${esc(x.name||'Student')}</span><span>${x.assessmentAverage==null?'—':x.assessmentAverage+'%'}</span><span>${x.homeworkSubmitted||0}/${x.homeworkTotal||0}</span><span>${x.activeInterventions||0}</span><span>${x.targetMet||0}</span></div>`).join('')}</div><p class="suite-note">Assessment averages are evidence from recorded course assessments, not official predicted grades.</p></section>`;}
  function exportReportCsv(p){if(!p)return;const rows=[['Student','Assessment average','Homework submitted','Homework total','Active interventions','Targets met'],...(p.students||[]).map(s=>[s.name,s.assessmentAverage??'',s.homeworkSubmitted||0,s.homeworkTotal||0,s.activeInterventions||0,s.targetMet||0])];const csv=rows.map(r=>r.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(',')).join('\n');const blob=new Blob([csv],{type:'text/csv'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`${String(p.className||'class').replace(/[^a-z0-9]+/gi,'-').toLowerCase()}-report.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500);}

  // Phase 14 — Parent Summaries
  function renderParents(){const root=body();if(!root)return;root.innerHTML=`${phaseHead(14,'Parent Summaries','Create a concise learning-progress summary from recorded evidence without exposing private teacher notes.')}
    <form class="suite-card suite-form" data-parent-form><label>Class<select name="class_id" data-parent-class required>${classOptions()}</select></label><label>Student<select name="student_id" data-parent-student required><option value="">Choose a class first…</option></select></label><div class="wide"><button class="button primary" type="submit">Generate parent summary</button></div></form>${state.parentSummary?parentSummaryHtml(state.parentSummary.payload||state.parentSummary):''}`;
    const form=root.querySelector('[data-parent-form]'),c=form.elements.class_id,st=form.elements.student_id;const refresh=()=>{st.innerHTML='<option value="">Choose student…</option>'+joinedFor(c.value).map(m=>`<option value="${m.student_id}">${esc(m.display_name||m.student_email)}</option>`).join('');};c.addEventListener('change',refresh);refresh();form.addEventListener('submit',generateParentSummary);root.querySelector('[data-parent-copy]')?.addEventListener('click',()=>copyParentSummary(state.parentSummary?.payload||state.parentSummary));}
  async function generateParentSummary(e){e.preventDefault();const fd=new FormData(e.currentTarget);const {data,error}=await sb().rpc('gcse_build_parent_summary',{p_class_id:String(fd.get('class_id')||''),p_student_id:String(fd.get('student_id')||'')});if(error){message(error.message,'error');return;}state.parentSummary=data;message('Parent summary generated.','success');renderParents();}
  function parentSummaryHtml(p){return `<section class="suite-card parent-summary"><div class="suite-card-head"><div><span>Parent/carer progress summary</span><h3>${esc(p.studentName||'Student')}</h3><p>${esc(p.className||'')}</p></div><button class="button" data-parent-copy>Copy summary</button></div><p class="parent-summary-lead">${esc(p.summary||'')}</p><div class="suite-kpis compact"><article><span>Assessment evidence</span><strong>${p.assessmentAverage==null?'—':p.assessmentAverage+'%'}</strong></article><article><span>Homework</span><strong>${p.homeworkSubmitted||0}/${p.homeworkRecorded||0}</strong></article><article><span>Interventions</span><strong>${p.interventions||0}</strong></article><article><span>Targets met</span><strong>${p.targetsMet||0}</strong></article></div><h4>Suggested next steps</h4><ul>${(p.nextSteps||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><small>${esc(p.note||'')}</small></section>`;}
  async function copyParentSummary(p){if(!p)return;const text=`${p.studentName} — ${p.className}\n\n${p.summary}\n\nNext steps:\n${(p.nextSteps||[]).map(x=>`• ${x}`).join('\n')}\n\n${p.note||''}`;try{await navigator.clipboard.writeText(text);message('Parent summary copied.','success');}catch{message('Copy failed. Select the text manually.','error');}}

  // Phase 15 — Department Dashboard
  async function renderDepartment(){const root=body();if(!root)return;root.innerHTML=`${phaseHead(15,'Department Dashboard','Bring teacher classes together for department-level visibility without exposing data outside the department membership list.')}
    <div class="suite-two-col"><form class="suite-card suite-form" data-dept-create><label class="wide">Department name<input name="name" maxlength="120" placeholder="Science Department" required></label><label class="wide">Description<textarea name="description" rows="2" placeholder="Optional"></textarea></label><div class="wide"><button class="button primary" type="submit">Create department</button></div></form><section class="suite-card"><h3>Your departments</h3><div class="suite-choice-list">${state.departments.length?state.departments.map(d=>`<button type="button" data-dept-open="${d.id}"><strong>${esc(d.name)}</strong><span>${esc(d.description||'Open dashboard')}</span></button>`).join(''):'<div class="teacher-suite-empty">No department workspace yet.</div>'}</div></section></div><div data-dept-dashboard>${state.departmentDashboard?departmentDashboardHtml(state.departmentDashboard):''}</div>`;
    root.querySelector('[data-dept-create]')?.addEventListener('submit',createDepartment);root.querySelectorAll('[data-dept-open]').forEach(b=>b.addEventListener('click',()=>openDepartment(b.dataset.deptOpen)));bindDepartmentActions();}
  async function createDepartment(e){e.preventDefault();const fd=new FormData(e.currentTarget),{error}=await sb().rpc('gcse_create_department',{p_name:String(fd.get('name')||''),p_description:String(fd.get('description')||'')});if(error){message(error.message,'error');return;}await loadBase();message('Department created.','success');renderDepartment();}
  async function openDepartment(id){const {data,error}=await sb().rpc('gcse_department_dashboard',{p_department_id:id});if(error){message(error.message,'error');return;}state.departmentDashboard=data;renderDepartment();}
  function departmentDashboardHtml(d){const s=d.summary||{};return `<section class="suite-card department-dashboard" data-active-department="${d.department?.id||''}"><div class="suite-card-head"><div><span>Department dashboard</span><h3>${esc(d.department?.name||'Department')}</h3><p>${esc(d.department?.description||'')}</p></div><button class="button" data-go-collaboration>Open collaboration</button></div><div class="suite-kpis"><article><span>Teachers</span><strong>${s.teachers||0}</strong></article><article><span>Classes</span><strong>${s.classes||0}</strong></article><article><span>Students</span><strong>${s.students||0}</strong></article><article><span>Assessment avg</span><strong>${s.assessmentAverage==null?'—':s.assessmentAverage+'%'}</strong></article></div><form class="suite-form suite-inline-form" data-dept-add><input type="email" name="email" placeholder="teacher@school.org" required><select name="role"><option value="teacher">Teacher</option><option value="lead">Department lead</option></select><button class="button primary" type="submit">Add teacher</button></form><div class="suite-list">${(d.members||[]).map(m=>`<article><div><strong>${esc(m.email||'Teacher account')}</strong><small>${esc(titleCase(m.role))}</small></div></article>`).join('')}</div></section>`;}
  function bindDepartmentActions(){const root=body(),card=root?.querySelector('[data-active-department]');if(!card)return;card.querySelector('[data-dept-add]')?.addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.currentTarget),id=card.dataset.activeDepartment,{error}=await sb().rpc('gcse_department_add_teacher',{p_department_id:id,p_email:String(fd.get('email')||''),p_role:String(fd.get('role')||'teacher')});if(error){message(error.message,'error');return;}message('Teacher added to department.','success');openDepartment(id);});card.querySelector('[data-go-collaboration]')?.addEventListener('click',()=>{state.tab='collaboration';renderNav();renderCollaboration(card.dataset.activeDepartment);});}

  // Phase 16 — Teacher Collaboration
  async function loadCollaboration(deptId){if(!deptId){state.collaboration=[];state.comments=[];return;}const [items,comments]=await Promise.all([sb().from('gcse_collaboration_items').select('*').eq('department_id',deptId).order('created_at',{ascending:false}),sb().from('gcse_collaboration_comments').select('*').eq('department_id',deptId).order('created_at')]);state.collaboration=items.data||[];state.comments=comments.data||[];}
  async function renderCollaboration(preselect){const root=body();if(!root)return;const deptId=preselect||state.departmentDashboard?.department?.id||state.departments[0]?.id||'';if(deptId)await loadCollaboration(deptId);root.innerHTML=`${phaseHead(16,'Teacher Collaboration','Share lesson ideas, resources and strategies inside an explicit department workspace.')}
    <div class="suite-filter"><label>Department<select data-collab-dept><option value="">Choose department…</option>${state.departments.map(d=>`<option value="${d.id}" ${d.id===deptId?'selected':''}>${esc(d.name)}</option>`).join('')}</select></label></div>${deptId?`<form class="suite-card suite-form" data-collab-create data-dept="${deptId}"><label>Type<select name="item_type"><option value="note">Note</option><option value="resource">Resource idea</option><option value="lesson_plan">Lesson plan</option><option value="strategy">Teaching strategy</option></select></label><label>Title<input name="title" maxlength="160" required></label><label class="wide">Share with department<textarea name="body" rows="3" required></textarea></label><div class="wide"><button class="button primary" type="submit">Share</button></div></form><div class="collab-feed">${state.collaboration.length?state.collaboration.map(collaborationCard).join(''):'<div class="teacher-suite-empty">Nothing shared yet.</div>'}</div>`:'<div class="teacher-suite-empty">Create or choose a department first.</div>'}`;
    root.querySelector('[data-collab-dept]')?.addEventListener('change',e=>renderCollaboration(e.target.value));root.querySelector('[data-collab-create]')?.addEventListener('submit',createCollaborationItem);root.querySelectorAll('[data-collab-comment-form]').forEach(f=>f.addEventListener('submit',addComment));}
  function collaborationCard(item){const comments=state.comments.filter(c=>c.item_id===item.id);return `<article class="suite-card collab-card"><div class="suite-card-head"><div><span>${esc(titleCase(item.item_type))} · ${esc(fmt(item.created_at))}</span><h3>${esc(item.title)}</h3></div></div><p>${esc(item.content?.body||'')}</p><div class="collab-comments">${comments.map(c=>`<div><span>Teacher</span><p>${esc(c.body)}</p></div>`).join('')}</div><form data-collab-comment-form data-item="${item.id}" data-dept="${item.department_id}"><input name="body" maxlength="2000" placeholder="Add a comment…" required><button type="submit">Comment</button></form></article>`;}
  async function createCollaborationItem(e){e.preventDefault();const fd=new FormData(e.currentTarget),dept=e.currentTarget.dataset.dept;const {error}=await sb().from('gcse_collaboration_items').insert({department_id:dept,author_id:uid(),item_type:String(fd.get('item_type')||'note'),title:String(fd.get('title')||'').trim(),content:{body:String(fd.get('body')||'').trim()}});if(error){message(error.message,'error');return;}message('Shared with department.','success');renderCollaboration(dept);}
  async function addComment(e){e.preventDefault();const fd=new FormData(e.currentTarget),{error}=await sb().from('gcse_collaboration_comments').insert({item_id:e.currentTarget.dataset.item,department_id:e.currentTarget.dataset.dept,author_id:uid(),body:String(fd.get('body')||'').trim()});if(error){message(error.message,'error');return;}renderCollaboration(e.currentTarget.dataset.dept);}

  // Phase 17 — School Admin
  async function renderSchool(){const root=body();if(!root)return;if(!schoolAdminEligible()){root.innerHTML=`${phaseHead(17,'School Admin','School-wide controls are restricted to School Admin or Platform Admin accounts.')}<div class="teacher-suite-empty"><strong>School Admin access required</strong><p>Your Teacher tools remain available in Phases 8–16.</p></div>`;return;}const activeId=state.schoolDashboard?.school?.id||state.schools[0]?.id||'';if(activeId&&!state.schoolDashboard){const x=await sb().rpc('gcse_school_dashboard',{p_school_id:activeId});if(!x.error)state.schoolDashboard=x.data;}root.innerHTML=`${phaseHead(17,'School Admin','Manage school membership and view school-wide usage of the GCSE Science teacher platform.')}
    <div class="suite-two-col"><form class="suite-card suite-form" data-school-create><label class="wide">School name<input name="name" maxlength="160" required></label><div class="wide"><button class="button primary" type="submit">Create school workspace</button></div></form><section class="suite-card"><h3>School workspaces</h3><div class="suite-choice-list">${state.schools.length?state.schools.map(s=>`<button data-school-open="${s.id}"><strong>${esc(s.name)}</strong><span>Open dashboard</span></button>`).join(''):'<div class="teacher-suite-empty">No school workspace yet.</div>'}</div></section></div>${state.schoolDashboard?schoolDashboardHtml(state.schoolDashboard):''}`;root.querySelector('[data-school-create]')?.addEventListener('submit',createSchool);root.querySelectorAll('[data-school-open]').forEach(b=>b.addEventListener('click',()=>openSchool(b.dataset.schoolOpen)));bindSchoolActions();}
  async function createSchool(e){e.preventDefault();const fd=new FormData(e.currentTarget),{data,error}=await sb().rpc('gcse_create_school',{p_name:String(fd.get('name')||'')});if(error){message(error.message,'error');return;}await loadBase();state.schoolDashboard=null;message('School workspace created.','success');openSchool(data.id);}
  async function openSchool(id){const {data,error}=await sb().rpc('gcse_school_dashboard',{p_school_id:id});if(error){message(error.message,'error');return;}state.schoolDashboard=data;renderSchool();}
  function schoolDashboardHtml(d){const s=d.summary||{};return `<section class="suite-card school-dashboard" data-active-school="${d.school?.id||''}"><div class="suite-card-head"><div><span>School dashboard</span><h3>${esc(d.school?.name||'School')}</h3></div></div><div class="suite-kpis"><article><span>Staff</span><strong>${s.staff||0}</strong></article><article><span>Classes</span><strong>${s.classes||0}</strong></article><article><span>Students</span><strong>${s.students||0}</strong></article><article><span>Assessment avg</span><strong>${s.assessmentAverage==null?'—':s.assessmentAverage+'%'}</strong></article><article><span>Active interventions</span><strong>${s.activeInterventions||0}</strong></article></div><form class="suite-form suite-inline-form" data-school-add><input type="email" name="email" placeholder="staff@school.org" required><select name="role"><option value="teacher">Teacher</option><option value="department_lead">Department lead</option><option value="admin">School admin</option></select><button class="button primary" type="submit">Add staff</button></form><div class="suite-list">${(d.staff||[]).map(m=>`<article><div><strong>${esc(m.email||'GCSE account')}</strong><small>${esc(titleCase(m.role))}</small></div></article>`).join('')}</div></section>`;}
  function bindSchoolActions(){const card=body()?.querySelector('[data-active-school]');if(!card)return;card.querySelector('[data-school-add]')?.addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.currentTarget),id=card.dataset.activeSchool,{error}=await sb().rpc('gcse_school_add_staff',{p_school_id:id,p_email:String(fd.get('email')||''),p_role:String(fd.get('role')||'teacher')});if(error){message(error.message,'error');return;}message('Staff membership updated.','success');openSchool(id);});}

  // Student-side live classroom entry point for Phase 8.
  async function renderStudentLive(){
    const content=document.getElementById('gcseAuthContent');if(!content||!session()?.user||teacherEligible())return;
    content.querySelector('[data-student-live-classroom]')?.remove();
    const panel=document.createElement('section');panel.className='student-live-classroom';panel.dataset.studentLiveClassroom='true';panel.innerHTML=`<div><span class="gcse-auth-eyebrow">Live classroom</span><h3>Join your teacher</h3><p>Enter the six-character code shown by your teacher.</p></div><form data-live-student-join><input name="code" maxlength="8" autocomplete="off" placeholder="ABC123" required><button type="submit">Join</button></form><div data-live-student-area></div>`;
    content.querySelector('#gcseSignOut')?.insertAdjacentElement('beforebegin',panel);panel.querySelector('[data-live-student-join]')?.addEventListener('submit',studentJoinLive);
  }
  async function studentJoinLive(e){e.preventDefault();const fd=new FormData(e.currentTarget),area=e.currentTarget.parentElement.querySelector('[data-live-student-area]'),{data,error}=await sb().rpc('gcse_join_live_classroom',{p_code:String(fd.get('code')||'').trim()});if(error){area.innerHTML='<p class="student-live-error">That live classroom is not available for your account.</p>';return;}renderStudentLiveActivity(area,data);}
  function renderStudentLiveActivity(area,data){const prompt=data.payload?.prompt||'';area.innerHTML=`<div class="student-live-active"><span>${esc(titleCase(data.activity||'welcome'))}</span><strong>${esc(data.title||'Live classroom')}</strong>${prompt?`<p>${esc(prompt)}</p><form data-student-live-response><textarea name="response" rows="3" required placeholder="Your response…"></textarea><button type="submit">Send response</button></form>`:'<p>Your teacher has started the session. Wait for the first activity.</p>'}</div>`;area.querySelector('[data-student-live-response]')?.addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.currentTarget),{error}=await sb().rpc('gcse_submit_live_response',{p_session_id:data.id,p_prompt_id:data.activity||'response',p_response:String(fd.get('response')||''),p_payload:{}});if(error){e.currentTarget.insertAdjacentHTML('beforeend','<small>Response could not be saved.</small>');return;}e.currentTarget.innerHTML='<strong>Response sent.</strong><p>You can update it if your teacher asks you to try again.</p>';});}

  function phaseHead(n,title,description){return `<div class="suite-phase-head"><div><span>Phase ${n}</span><h2>${esc(title)}</h2><p>${esc(description)}</p></div></div>`;}

  function boot(){ensureModal();ensureButton();window.addEventListener('gcse-auth-changed',()=>{ensureButton();setTimeout(renderStudentLive,0);});window.addEventListener('gcse-access-changed',ensureButton);window.addEventListener('gcse-auth-account-rendered',()=>setTimeout(renderStudentLive,0));const observer=new MutationObserver(records=>{if(records.some(r=>[...r.addedNodes].some(n=>n.nodeType===1&&(n.matches?.('#gcseTeacherPlatformModal')||n.querySelector?.('#gcseTeacherPlatformModal')))))ensureButton();});observer.observe(document.body,{childList:true,subtree:true});}

  window.GCSE_TEACHER_SUITE={open:openSuite,openPhase:n=>{const hit=TABS.find(x=>Number(x[1])===Number(n));openSuite(hit?.[0]||'live');},refresh:async()=>{await loadBase();renderTab();}};
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot();
})();